import{_ as c,l as d,o as a,c as l,v as r,p as i,x as o,d as n,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"RCU 宽限期","description":"","frontmatter":{"title":"RCU 宽限期","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rcu-gp.md","filePath":"cs/rcu-gp.md","lastUpdated":1789023840000}'),_={name:"cs/rcu-gp.md"};function h(u,e,C,m,P,A){const t=d("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="rcu-宽限期" tabindex="-1">RCU 宽限期 <a class="header-anchor" href="#rcu-宽限期" aria-label="Permalink to &quot;RCU 宽限期&quot;">​</a></h1><div class="epigraph"><p>宽限期结束，意味着开始等待之后启动的每个 CPU 都已经过了一次静止状态——于是那时还活着的 RCU 读者都已离开。</p><footer>—— 据 McKenney, RCU 实现与《Is Parallel Programming Hard》中对 grace period 的整理</footer></div><p><a href="/cs/rcu-read">上一课</a>禁止在读侧释放旧结点。缺口是检测「世界上没有读者还拿着旧指针」：<strong>grace period（宽限期）</strong>。写者 <code>synchronize_rcu</code> 阻塞到一个宽限期结束，或 <code>call_rcu</code> 把释放挂到结束后的回调。本课钉静止状态直觉，不当成内核源码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不能给每个读者发票再回收：那等于又一把读锁。RCU 用 CPU 的静止：不在 <code>rcu_read_lock</code> 区间内（对抢占 RCU：该核上读侧嵌套为零）。若每个 CPU 都经历过一次静止，则任何在宽限期开始前已进入的读者都已退出——因为读者不可睡、不可被迁走而一直占着读侧（经典模型）。缺口不是再写 <code>rcu_dereference</code>，而是这条<strong>全局静止论证</strong>。</p><p><span class="marginnote"><code>synchronize_rcu</code> 可能等若干毫秒，写路径不能在硬 IRQ 里做。<code>call_rcu</code> 把 free 推迟到软中断或工作队列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写者发布新指针（release）后，等待宽限期，再 <code>kfree</code> 旧结点。实现：每 CPU 记 qs 位，时钟或上下文切换报告静止，协调者收集全 1 则 GP 结束。多个写者可共享同一 GP。与<a href="/cs/idle-thread">idle</a>：idle 通常算静止，否则空闲核会挡住回收。</p>',8)),(a(),i(p,null,{default:o(()=>[s(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUB%5B%22%E5%8F%91%E5%B8%83%E6%96%B0%E6%8C%87%E9%92%88%22%5D%20--%3E%20GP%5B%22%E7%AD%89%E6%89%80%E6%9C%89%20CPU%20%E9%9D%99%E6%AD%A2%E4%B8%80%E6%AC%A1%22%5D%0A%20%20GP%20--%3E%20FREE%5B%22%E9%87%8A%E6%94%BE%E6%97%A7%E7%BB%93%E7%82%B9%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与<a href="/cs/completion">completion</a> 不同：不是等一个生产者，而是等所有可能读者的核过静止。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>宽限期把内存回收延迟变成可证明的安全点。它是写者的税、读者的零税。过长的读侧临界区拖长 GP，表现为内存峰值——纪律仍是读侧要短。抢占 RCU、SRCU 改静止定义，本课只要求：释放前必须经过实现所承认的 GP。</p><p>NMI 中的读者要用特殊登记，否则静止检测看不见它们；点到即可。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Expedited GP 的 IPI 风暴写成运维事故分析，不列举所有 <code>rcu_barrier</code> 语义。无锁 CAS 循环另有 ABA，下一课。也不把 GC 分代与 RCU 混成一种运行时。</p><p>后课默认：RCU 释放发生在宽限期后。无锁结构用 CAS 换头时，节点被复用会对 CAS 撒谎，下一课 ABA。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宽限期：所有 CPU 静止过一次 ⇒ 旧读者已离开，可释放。</li><li>写者付延迟；读侧过长会拖回收。</li><li>无锁 CAS 的 ABA 是下一课。</li><li>出处：McKenney，RCU 文献与 <em>Is Parallel Programming Hard, and, If So, What Can You Do About It?</em>。</li></ul>',9))])}const U=c(_,[["render",h]]);export{E as __pageData,U as default};
